exercises.solution:
const jezyki = new Set();
jezyki.add("pl");
jezyki.add("de");
jezyki.add("fr");

console.log(jezyki.has("pl")); // true
console.log(jezyki.has("es")); // false

const imiona = new Set(["Ala", "Bea", "Ala", "Cela"]);
imiona.delete("Bea");
console.log(imiona); // Set(2) {"Ala", "Cela"}

const liczby = new Set([2, 4, 6]);
console.log(liczby.has(4)); // true
liczby.delete(4);
console.log(liczby.has(4)); // false

const zbior = new Set([1, "1", true, 1]);
console.log(zbior.size); // 3
// Set rozroznia typy wartosci, wiec liczba 1 (number) i string "1" to
// DWIE ROZNE wartosci, mimo ze "wygladaja podobnie". Wartosc true rowniez
// jest osobnym typem (boolean). Druga liczba 1 w tablicy jest DUPLIKATEM
// pierwszej (ten sam typ i wartosc), wiec zostaje odrzucona - stad size = 3
// (1, "1", true), a nie 4.

const zbior = new Set([5, 5, 7, 7, 7, 9]);
const tablica = [...zbior];
console.log(tablica); // [5, 7, 9]

const litery = new Set(["a", "b", "c"]);
for (const litera of litery) {
  console.log(litera);
}
// a, b, c

const oceny = [3, 4, 4, 5, 5, 5, 2];
const unikalneOceny = [...new Set(oceny)];
console.log(unikalneOceny); // [3, 4, 5, 2]
